import {getLocale} from './i18n.js';
import {deckLayout} from './deck-layout.js';
import {boatScale} from './boats.js';
import {clamp} from './constants.js';
import {spinPoleRig,headsailInhaulAllowed} from './orc-sails.js';
// Distinct, restrained rope colours. A control keeps its colour in 3D and in the editor.
export const CONTROL_COLORS=Object.freeze({
 'main.halyard':'#d07b91','main.cunningham':'#c98fb6','main.outhaul':'#91b995','main.traveler':'#ddc16e','main.sheet':'#de906f','main.battens':'#b8c797','main.vang':'#bfa780','main.twist':'#879ad3',
 'genoa.car':'#68bdb7','genoa.barber':'#e3a1c6','genoa.sheet':'#70aee1','genoa.halyard':'#ad96c8','genoa.battens':'#9bbaa5','genoa.twist':'#8ca4ca',
 'spinnaker.halyard':'#c57ea7','spinnaker.sheet':'#b391d2','spinnaker.brace':'#d5ad67','spinnaker.poleLift':'#b4c871','spinnaker.barberSheet':'#cb9184','spinnaker.barberBrace':'#75bbb0',
 'gennaker.halyard':'#7895ca','gennaker.tack':'#ca9ca7','gennaker.sheet':'#79b69b','rig.backstay':'#b6a3c5','rig.forestay':'#c7ba8e','rig.shrouds':'#a2b9ce'
});
export function controlSpec(category,key,state){const d=deckLayout(state),k=boatScale(state);if(category==='genoa'&&key==='sheet')return{min:0,max:120,step:1,unit:'%',low:'0% · completamente mollata',high:'120% · cazzata supplementare, fino al limite fisico'};if((category==='main'||category==='genoa')&&key==='twist')return{min:0,max:50,step:1,unit:'°',low:'0° · vela non svergolata',high:'50° · massimo twist'};if(category==='spinnaker'&&key==='poleLift'){const pole=spinPoleRig(state);return{min:pole.low*k,max:pole.high*k,step:.001,unit:'m',position:true,low:'Caricabasso · abbassa',high:'Caricalto · alza'};}if(category==='genoa'&&key==='barber'){const outOnly=!headsailInhaulAllowed(state);return{min:outOnly?0:-100,max:100,step:1,unit:'%',position:false,centered:true,outOnly,low:outOnly?'Sul carrello':'Verso l’albero',high:'Verso l’esterno'};}if(category==='main'&&key==='traveler')return{min:-d.cockpitHalfWidth*k,max:d.cockpitHalfWidth*k,step:.001,unit:'m',position:true,low:(state?.windAngle??52)<0?'Sopravento':'Sottovento',high:(state?.windAngle??52)<0?'Sottovento':'Sopravento'};if(category==='genoa'&&key==='car')return{min:0,max:(d.genoaTrackForward-d.genoaTrackAft)*k,step:.001,unit:'m',position:true,low:'Fine corsa a poppa',high:'A prua delle sartie'};return{min:0,max:100,step:1,unit:'%',position:false};}
export function controlToValue(category,key,value,state){const p=controlSpec(category,key,state);if(p.outOnly)return clamp((value-50)*2,0,100);if(p.position||p.centered)return value<=0?p.min:value>=100?p.max:p.min+(p.max-p.min)*value/100;return value;}
export function valueToControl(category,key,value,state){const p=controlSpec(category,key,state),v=clamp(p.position?Number(value):Math.round(Number(value)/p.step)*p.step,p.min,p.max);if(p.outOnly)return 50+v/2;return p.position||p.centered?(v-p.min)/(p.max-p.min)*100:v;}
export function formatControlValue(category,key,value,state){if(key==='sheet'&&Number.isFinite(state?.fixedSheetLengths?.[category]))return state.fixedSheetLengths[category].toLocaleString(getLocale(),{maximumFractionDigits:3})+' m';const p=controlSpec(category,key,state),v=controlToValue(category,key,value,state);if(p.centered)return Math.abs(v)<.5?'Sul carrello':`${Math.abs(v).toFixed(0)}% ${v<0?'interno':'esterno'}`;return v.toLocaleString(getLocale(),{minimumFractionDigits:p.position?3:0,maximumFractionDigits:p.position?3:0})+' '+p.unit;}
export function controlPositionDescription(category,key,value,state){if(key==='twist')return `${Math.round(clamp(Number(value),0,50))}° fra piede e penna · rotazione lineare proporzionale all’altezza`;if(category==='spinnaker'&&key==='brace')return `${Math.round(spinPoleRig(state).azimuth*180/Math.PI)}° quadratura tangone · ${Math.round(value)}% braccio`;if(key==='sheet'&&Number.isFinite(state?.fixedSheetLengths?.[category]))return state.fixedSheetLengths[category].toLocaleString(getLocale(),{maximumFractionDigits:3})+' m di cima fermata · posizione calcolata sotto carico';const p=controlSpec(category,key,state),v=controlToValue(category,key,value,state);if(category==='spinnaker'&&key==='poleLift')return `Varea a ${v.toLocaleString(getLocale(),{minimumFractionDigits:3,maximumFractionDigits:3})} m dal riferimento dell’acqua · caricalto e caricabasso coordinati`;if(p.centered)return Math.abs(v)<.5?'Rinvio centrato sul carrello':`${Math.abs(v).toFixed(0)}% ${v<0?'verso l’albero':'verso l’esterno'}`;if(category==='main'&&key==='traveler')return Math.abs(v)<.0005?'Carrello al centro del pozzetto':`${Math.abs(v).toLocaleString(getLocale(),{minimumFractionDigits:3,maximumFractionDigits:3})} m ${v*((state?.windAngle??52)<0?-1:1)>0?'sopravento':'sottovento'} dal centro`;if(category==='genoa'&&key==='car')return`${v.toLocaleString(getLocale(),{minimumFractionDigits:3,maximumFractionDigits:3})} m dal fine corsa di poppa · carrelli simmetrici`;return category==='genoa'&&key==='sheet'?`${Math.round(value)}% · 100% fine corsa normale · 120% cazzata supplementare entro il limite dell’armo`:key==='sheet'?`${Math.round(value)}% della corsa utile · 0 libera · 100 massimo al rinvio`:`${Math.round(value)}% · tensione relativa`;}
